content.arguments:
{"file_path": "C:\Users\九幽\.dsh-qq\scripts\memory-compact.mjs", "content": "#!/usr/bin/env node
// memory-compact.mjs — 记忆层机械压缩助手
// 只读原件，只出报告。不做任何自动改写：合并/删除永远由人（或模型）确认。
//
// 用法:
//   node memory-compact.mjs            # 生成报告
//   node memory-compact.mjs --json     # 机器可读输出

import fs from 'node:fs'
import path from 'node:path'

const HOME = process.env.USERPROFILE || 'C:/Users/九幽'
const MEM_DIR = path.join(HOME, '.dsh-qq', 'memory-repo', 'short')
const OUT_DIR = path.join(HOME, '.dsh-qq', 'memory-repo', 'meta')
const FILES = ['MEMORY.md', 'USER.md', 'STANDING.md']
const STALE_DAYS = 30
const NEAR_DUP = 0.45
const TOPIC_OVERLAP = 0.25

const today = new Date()
const dayDiff = (d) => Math.round((today - d) / 86400000)

// ---------- 解析 ----------
function parseEntries(file) {
  if (!fs.existsSync(file)) return []
  const raw = fs.readFileSync(file, 'utf8')
  return raw
    .split(/\n\s*§\s*\n/)
    .map((block) => block.trim())
    .filter(Boolean)
    .map((block) => {
      const meta = /<!--\s*created=([\d-]+),\s*last=([\d-]+)\s*-->/.exec(block)
      const body = block.replace(/<!--[\s\S]*?-->/g, '').trim()
      return {
        body,
        created: meta ? meta[1] : null,
        last: meta ? meta[2] : null,
        chars: body.length,
      }
    })
}

// ---------- 相似度：中文 2-gram Jaccard ----------
const STOP = new Set(['的', '了', '是', '我', '你', '他', '在', '和', '也', '就', '都', '要', '不', '有', '这', '那', '个', '上', '下'])
function grams(text) {
  const clean = text
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/[A-Za-z]:[\\/][^\s，。；、）]*/g, ' ') // 路径噪声
    .replace(/[\s\d_\-:：，。！？、；「」（）()【】\[\]<>.,;!?'"`~@#$%^&*+=|\\/]/g, '')
  const set = new Set()
  for (let i = 0; i < clean.length - 1; i++) {
    const g = clean.slice(i, i + 2)
    if (STOP.has(g[0]) && STOP.has(g[1])) continue
    set.add(g)
  }
  return set
}
function jaccard(a, b) {
  if (!a.size || !b.size) return 0
  let inter = 0
  for (const g of a) if (b.has(g)) inter++
  return inter / (a.size + b.size - inter)
}

// ---------- 主流程 ----------
const report = { generatedAt: today.toISOString(), files: {}, pairs: [], stale: [], budget: {} }

for (const name of FILES) {
  const file = path.join(MEM_DIR, name)
  const entries = parseEntries(file)
  entries.forEach((e, i) => (e.id = `${name}#${i + 1}`))
  entries.forEach((e) => (e.grams = grams(e.body)))
  report.files[name] = entries.map(({ grams, ...rest }) => rest)
  report.budget[name] = entries.reduce((s, e) => s + e.chars, 0)

  // 近似重复
  for (let i = 0; i < entries.length; i++) {
    for (let j = i + 1; j < entries.length; j++) {
      const sim = jaccard(entries[i].grams, entries[j].grams)
      if (sim >= NEAR_DUP) {
        report.pairs.push({
          a: entries[i].id, b: entries[j].id,
          sim: +sim.toFixed(2),
          aHead: entries[i].body.slice(0, 60),
          bHead: entries[j].body.slice(0, 60),
        })
      }
    }
  }

  // 陈旧
  for (const e of entries) {
    if (!e.last) continue
    const d = dayDiff(new Date(e.last))
    if (d >= STALE_DAYS) report.stale.push({ id: e.id, days: d, head: e.body.slice(0, 60) })
  }
}

report.pairs.sort((x, y) => y.sim - x.sim)
report.stale.sort((x, y) => y.days - x.days)

// ---------- 输出 ----------
if (process.argv.includes('--json')) {
  console.log(JSON.stringify(report, null, 2))
  process.exit(0)
}

const L = []
L.push('# 记忆压缩报告')
L.push('')
L.push(`生成: ${report.generatedAt}`)
L.push('')
L.push('## 体量')
for (const [k, v] of Object.entries(report.budget)) L.push(`- ${k}: ${(v / 1000).toFixed(1)}k 字符`)
L.push('')
L.push(`## 近似重复（相似度 ≥ ${NEAR_DUP}）`)
if (!report.pairs.length) L.push('- 没有。')
for (const p of report.pairs) {
  L.push(`- ${p.sim}  ${p.a} ↔ ${p.b}`)
