/** W2-③: proactive-write audit file name, appended under mediaDir (jsonl). */
export const ACTION_AUDIT_FILE = 'qq-actions.log';
/**
 * [patch 2026-10-27] 上下文泄漏拦截。
 * 判据收紧过一版：第一版只要出现标签名就丢，结果把正常解释也吞了。
 * 现在只认「结构」——闭合标签，或带属性的开场标签 + 明显过长的正文。
 * 单纯在句子里提到 <user_message> 这种不算泄漏。
 */
export const LEAK_CLOSERS = [
    '</user_message>',
    '</thought>',
    '</analysis>',
    '</tool_call>',
    '</function_call>',
];
export const LEAK_OPENERS = [
    '<user_message qq=',
    '<user_message nickname=',
    '<thought>',
    '<analysis>',
    '<tool_call>',
    '<function_call>',
];
/** 文本是否疑似上下文/推理泄漏（结构判据，不靠零散标签名）。 */
export function looksLikeLeakedContext(text) {
    if (typeof text !== 'string' || text === '')
        return false;
    const head = text.slice(0, 4000);
    if (LEAK_CLOSERS.some((closer) => head.includes(closer)))
        return true;
    const hasOpener = LEAK_OPENERS.some((opener) => head.includes(opener));
    // 开标签 + 长正文才判泄漏；短句里提到标签名是正常聊天。
    return hasOpener && head.length >= 300;
}

