  [Parameter(Mandatory=$true)][string]$Video,
  [int]$MaxFrames = 12,
  [int]$Scale = 800,
  [switch]$Scene
)
$ErrorActionPreference = 'Stop'

$bin = 'C:\Users\九幽\tools\ffmpeg-9.0.2-essentials_build\bin'
$ffmpeg = Join-Path $bin 'ffmpeg.exe'
$ffprobe = Join-Path $bin 'ffprobe.exe'
if (-not (Test-Path $ffmpeg)) { throw "ffmpeg not found at $ffmpeg" }
if (-not (Test-Path $Video)) { throw "video not found: $Video" }

$meta = & $ffprobe -v error -select_streams v:0 `
  -show_entries stream=width,height -show_entries format=duration `
  -of json $Video 2>$null | ConvertFrom-Json
$width = $meta.streams[0].width
$height = $meta.streams[0].height
$duration = [double]$meta.format.duration

$name = [IO.Path]::GetFileNameWithoutExtension($Video)
$outDir = Join-Path $env:TEMP ("vidframes\" + $name)
if (Test-Path $outDir) { Remove-Item $outDir -Recurse -Force }
New-Item -ItemType Directory -Force -Path $outDir | Out-Null

if ($Scene) {
  # 场景切换点抽帧：画面变化大的地方优先，适合教程/演示类视频
  & $ffmpeg -v error -i $Video -vf "select='gt(scene,0.25)',scale=${Scale}:-1" -vsync vfr -frames:v $MaxFrames "$outDir\s_%02d.jpg" 2>$null
} else {
  # 均匀抽帧：总时长切成 MaxFrames 段，每段取中点附近
  $interval = [Math]::Max($duration / $MaxFrames, 1)
  & $ffmpeg -v error -i $Video -vf "fps=1/$interval,scale=${Scale}:-1" -frames:v $MaxFrames "$outDir\f_%02d.jpg" 2>$null
}

$frames = @(Get-ChildItem $outDir -Filter *.jpg | Sort-Object Name | ForEach-Object {
  [pscustomobject]@{
    path = $_.FullName
    atSec = $null
    kb = [int]($_.Length / 1KB)
  }
})

# 帧很少时（短视频/长静止画面）退化成首尾两帧
if ($frames.Count -eq 0) {
  & $ffmpeg -v error -i $Video -vf "scale=${Scale}:-1" -frames:v 1 "$outDir\f_01.jpg" 2>$null
  $frames = @(Get-ChildItem $outDir -Filter *.jpg | ForEach-Object {
    [pscustomobject]@{ path = $_.FullName; atSec = $null; kb = [int]($_.Length / 1KB) }
  })
}

$result = [pscustomobject]@{
  video = $Video
  duration = [Math]::Round($duration, 1)
  width = $width
  height = $height
  frameDir = $outDir
  frameCount = $frames.Count
  frames = $frames
}
$result | ConvertTo-Json -Depth 4
