{"content": "#!/usr/bin/env node
// agnes.mjs — Agnes AI 的生图 / 生视频命令行（给林晚用）
//
// 用法:
//   node agnes.mjs image "<prompt>" [--out 目录] [--size 1024x1024] [--model agnes-image-2.5-flash]
//   node agnes.mjs video "<prompt>" [--out 目录] [--image <url|本地路径>] [--frames 121] [--fps 24]
//   node agnes.mjs status <task_id>
//
// 输出: JSON { ok, kind, path|taskId, url, ms }
// key 从 C:\Users\九幽\.dsh-qq\keys\agnes.txt 读，不接受命令行传入。

import fs from 'node:fs'
import path from 'node:path'

const KEY_FILE = 'C:/Users/九幽/.dsh-qq/keys/agnes.txt'
const BASE = 'https://apihub.agnes-ai.com/v1'
const DEFAULT_OUT = 'C:/Users/九幽/.dsh-qq/media/agnes'
const VIDEO_POLL_MS = 5000
const VIDEO_TIMEOUT_MS = 15 * 60 * 1000

const args = process.argv.slice(2)
const cmd = args[0]
function flag(name, dflt) {
  const i = args.indexOf('--' + name)
  return i >= 0 && args[i + 1] ? args[i + 1] : dflt
}
function promptText() {
  const i = args.indexOf('--')
  if (i > 0) return args.slice(0, i).filter((a) => !a.startsWith('--')).slice(1).join(' ')
  return args.slice(1).filter((a) => !a.startsWith('--')).join(' ')
}
function die(msg) { console.error(JSON.stringify({ ok: false, error: msg })); process.exit(1) }

const key = fs.existsSync(KEY_FILE) ? fs.readFileSync(KEY_FILE, 'utf8').trim() : ''
if (!key) die('missing key file: ' + KEY_FILE)

const headers = { Authorization: 'Bearer ' + key, 'Content-Type': 'application/json; charset=utf-8' }

async function api(url, init) {
  const res = await fetch(url, init)
  const text = await res.text()
  if (!res.ok) throw new Error('HTTP ' + res.status + ' ' + text.slice(0, 300))
  return text ? JSON.parse(text) : {}
}

async function download(url, dir, filename) {
  fs.mkdirSync(dir, { recursive: true })
  const dest = path.join(dir, filename)
  const res = await fetch(url)
  if (!res.ok) throw new Error('download HTTP ' + res.status)
  const buf = Buffer.from(await res.arrayBuffer())
  fs.writeFileSync(dest, buf)
  return dest
}

function stamp() {
  const d = new Date()
  const p = (n) => String(n).padStart(2, '0')
  return `${d.getFullYear()}${p(d.getMonth() + 1)}${p(d.getDate())}-${p(d.getHours())}${p(d.getMinutes())}${p(d.getSeconds())}`
}

async function cmdImage() {
  const prompt = promptText()
  if (!prompt) die('empty prompt')
  const outDir = flag('out', DEFAULT_OUT)
  const size = flag('size', '1024x1024')
  const model = flag('model', 'agnes-image-2.5-flash')
  const t0 = Date.now()
  const body = { model, prompt, n: 1, size }
  const r = await api(BASE + '/images/generations', { method: 'POST', headers, body: JSON.stringify(body) })
  const url = r?.data?.[0]?.url
  if (!url) die('no url in response: ' + JSON.stringify(r).slice(0, 300))
  const ext = url.toLowerCase().endsWith('.jpg') || url.toLowerCase().endsWith('.jpeg') ? '.jpg' : '.png'
  const file = await download(url, outDir, `img-${stamp()}${ext}`)
  console.log(JSON.stringify({ ok: true, kind: 'image', path: file, url, taskId: r.task_id ?? null, ms: Date.now() - t0 }))
}

async function cmdVideo() {
  const prompt = promptText()
  if (!prompt) die('empty prompt')
  const outDir = flag('out', DEFAULT_OUT)
  const imageArg = flag('image', '')
  const body = {
    model: flag('model', 'agnes-video-2.5-flash'),
    prompt,
    width: Number(flag('width', 1152)),
    height: Number(flag('height', 768)),
    num_frames: Number(flag('frames', 121)),
    frame_rate: Number(flag('fps', 24)),
  }
  if (imageArg) {
    // 本地图片先转 data URL（API 只认 http/https，真发不出去时会给明确报错）
    body.image = imageArg.startsWith('http') ? imageArg : imageArg
  }
  const t0 = Date.now()
  const created = await api(BASE + '/videos', { method: 'POST', headers, body: JSON.stringify(body) })
  const id = created.id ?? created.task_id
  if (!id) die('no task id: ' + JSON.stringify(created).slice(0, 300))

  let last = created
  while (Date.now() - t0 < VIDEO_TIMEOUT_MS) {
    await new Promise((r) => setTimeout(r, VIDEO_POLL_MS))
    last = await api(BASE + '/videos/' + id, { headers })
    if (last.status === 'completed' || last.status === 'failed') break
    process.stderr.write(`[${last.status} ${last.progress ?? '?'}%]\n`)
  }
  if (last.status !== 'completed') {
    die('video not completed: ' + JSON.stringify({ id, status: last.status, progress: last.progress }).slice(0, 300))
  }
  const vurl = last.video_url ?? last.url
  if (!vurl) die('completed without url: ' + JSON.stringify(last).slice(0, 300))
  const file = await download(vurl, outDir, `vid-${stamp()}.mp4`)
  console.log(JSON.stringify({ ok: true, kind: 'video', path: file, url: vurl, taskId: id, ms: Date.now() - t0 }))
}

async function cmdStatus() {
  const id = args[1]
  if (!id) die('usage: status <task_id>')
  const r = await api(BASE + '/videos/' + id, { headers })
  console.log(JSON.stringify(r).slice(0, 1200))
}

try {
  if (cmd === 'image') await cmdImage()
  else if (cmd === 'video') await cmdVideo()
  else if (cmd === 'status') await cmdStatus()
  else die('usage: image|video|status')
} catch (e) {
  die(e.message)
}
