{"command": "$dir='C:\Users\九幽\.dsh-qq\keys'
function TestKey($name, $url){
  $f = Join-Path $dir $name
  if(-not (Test-Path $f)){ return "$name -> 文件不存在" }
  $k = [IO.File]::ReadAllText($f).Trim()
  try {
    $r = Invoke-RestMethod -Uri $url -Headers @{ Authorization = "Bearer $k" } -TimeoutSec 25
    $n = if($r.data){ @($r.data).Count } elseif($r.models){ @($r.models).Count } else { '-' }
    "$name -> OK  条目=$n"
  } catch {
    $resp=$_.Exception.Response
    if($resp){ "$name -> HTTP " + [int]$resp.StatusCode } else { "$name -> ERR " + $_.Exception.Message }
  }
