    base: 'https://open.bigmodel.cn/api/paas/v4',
    model: 'glm-5.3-flash',
  },
  openrouter: {
    file: 'open-router.txt',
    base: 'https://openrouter.ai/api/v1',
    model: 'liquid/lfm-2.5-2.6b:free',
    extraHeaders: { 'HTTP-Referer': 'http://localhost', 'X-Title': 'linwan' },
  },
}

const args = process.argv.slice(2)
const cmd = args[0]

function flag(name, dflt) {
  const i = args.indexOf('--' + name)
  return i >= 0 && args[i + 1] ? args[i + 1] : dflt
}
function textAfterCmd() {
  // 第一个不以 -- 开头的参数就是 prompt；带 -- 的参数跳过它的值
  const skipNext = new Set(['--p', '--m', '--sys', '--max', '--temp'])
  const parts = []
  for (let i = 1; i < args.length; i++) {
    const a = args[i]
    if (skipNext.has(a)) { i++; continue }
    if (a.startsWith('--')) continue
    parts.push(a)
  }
  return parts.join(' ').trim()
}
function die(msg) { console.error(JSON.stringify({ ok: false, error: msg })); process.exit(1) }

function keyFor(provider) {
  const p = PROVIDERS[provider]
  if (!p) die('unknown provider: ' + provider + ' (use: ' + Object.keys(PROVIDERS).join('|') + ')')
  const file = KEY_DIR + '/' + p.file
  if (!fs.existsSync(file)) die('missing key file: ' + file)
  return fs.readFileSync(file, 'utf8').trim()
}

async function api(url, init) {
  const res = await fetch(url, init)
  const text = await res.text()
  if (!res.ok) throw new Error('HTTP ' + res.status + ' ' + text.slice(0, 400))
  return text ? JSON.parse(text) : {}
}

async function cmdChat() {
  const provider = flag('p', 'siliconflow')
  const p = PROVIDERS[provider]
  const key = keyFor(provider)
  const prompt = textAfterCmd()
  if (!prompt) die('empty prompt')
  const model = flag('m', p.model)
  const sys = flag('sys', '')
  const messages = []
  if (sys) messages.push({ role: 'system', content: sys })
  messages.push({ role: 'user', content: prompt })

  const body = {
    model,
    messages,
    max_tokens: Number(flag('max', 512)),
    temperature: Number(flag('temp', 0.7)),
  }
  const headers = { Authorization: 'Bearer ' + key, 'Content-Type': 'application/json' }
  Object.assign(headers, p.extraHeaders ?? {})

  const t0 = Date.now()
  const r = await api(p.base + '/chat/completions', { method: 'POST', headers, body: JSON.stringify(body) })
  const msg = r?.choices?.[0]?.message ?? {}
  const out = msg.content ?? ''
  console.log(JSON.stringify({
    ok: true,
    provider,
    model,
    text: out,
    reasoning: msg.reasoning_content ? String(msg.reasoning_content).slice(0, 500) : undefined,
    usage: r.usage ?? null,
    ms: Date.now() - t0,
  }))
}

async function cmdModels() {
  const provider = flag('p', 'siliconflow')
  const p = PROVIDERS[provider]
  const key = keyFor(provider)
  const headers = { Authorization: 'Bearer ' + key }
  Object.assign(headers, p.extraHeaders ?? {})
  const r = await api(p.base + '/models', { headers })
  const ids = (r.data ?? r.models ?? []).map((m) => m.id)
  console.log(JSON.stringify({ ok: true, provider, count: ids.length, ids: ids.slice(0, 120) }))
}

try {
  if (cmd === 'chat') await cmdChat()
  else if (cmd === 'models') await cmdModels()
  else die('usage: chat|models')
} catch (e) {
  die(e.message)
}
